import{_ as t,o,c as n,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/88-测量误差.md","filePath":"books/xuehui-tiwen/88-测量误差.md","lastUpdated":1781367562000}'),s={name:"books/xuehui-tiwen/88-测量误差.md"};function i(l,a,d,c,p,_){return o(),n("div",null,[...a[0]||(a[0]=[e("h2",{id:"测量误差",tabindex:"-1"},[r("测量误差 "),e("a",{class:"header-anchor",href:"#测量误差","aria-label":'Permalink to "测量误差"'},"​")],-1),e("p",null,"统计结果来自测量，测量难免会有误差。新英格兰爱国者队于2015年被指控在对阵印第安纳波利斯小马队的一场重要比赛中给球泄了气，以更易于抓住传球。他们真的这么做了吗？",-1),e("p",null,"裁判在中场休息时对橄榄球进行了测量，爱国者队的球测量压力要比小马队的球测量压力小。但是等等，球不是在同一时间测量的：小马队的球是在爱国者队的球之后测量的。那又怎样呢？小马队的球放在一间温暖的房间里一些时间之后，才接受测量，球有更多时间对温度做出反应，以致球的压力增大了。因此，小马队的球被测量并被发现有更大的压力，其解释可能是“测量误差”，法院也同意爱国者队提出的这一论点。",-1),e("p",null,"另一个测量误差的例子是饮酒量的测量。辩护律师在这种情况下使用的一个成功策略是要求起诉方提供证据，证明用于判断血液酒精含量的设备最后一次校准的时间，然后要求提供校准设备本身的可靠性数据。换句话说，有两种装置被用作醉酒驾驶的依据，但只有在测量仪器保持准确和一致的情况下，该指控才有效。当它们不可靠时，血液酒精统计数据就不能为检察官的指控提供充分的依据。",-1)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
